import { finding } from '../../engine/checks/helpers/findings.mjs';

// The testable slice of the engineering-practices "earn each dependency" rule:
// only the event — a package.json gains a dependency it did not carry at the
// scoping base — has a signature; the judgment half stays in the skill this
// finding points to. Fires once, on the branch that adds the name, then
// converges; a group move or version bump is not an addition.

const DEP_KEYS = ['dependencies', 'devDependencies', 'peerDependencies', 'optionalDependencies'];

// Root or one directory down — the node pack's own marker scope, so a nested
// fixture/example manifest never counts.
const nearRoot = (f) => {
  const parts = f.split('/');
  return parts[parts.length - 1] === 'package.json' && parts.length <= 2;
};

function depNames(pkg) {
  const names = new Set();
  for (const key of DEP_KEYS) {
    for (const name of Object.keys(pkg?.[key] ?? {})) names.add(name);
  }
  return names;
}

const rule = {
  id: 'node/earn-each-dependency',
  severity: 'advisory',
  description: 'A newly added package.json dependency should be earned — prefer a built-in or a few lines for a narrow job',
  doc: 'packs/basics/RULES.md',
  scope: 'work',
  why: 'every dependency is standing surface area and supply-chain weight; a built-in or a few lines often covers a narrow job with none of it',

  run(work) {
    const out = [];
    for (const file of work.changedFiles.filter(nearRoot)) {
      const { head, base } = work.jsonPair(file);
      if (!head) continue;
      const carried = depNames(base);
      for (const key of DEP_KEYS) {
        for (const name of Object.keys(head[key] ?? {})) {
          if (carried.has(name)) continue;
          out.push(finding(rule, {
            file,
            what: `"${name}" added to ${key}`,
            fix: 'confirm it earns its place — a built-in or a few lines often does a narrow job with no dependency; if it is warranted this advisory needs no change',
          }));
        }
      }
    }
    return out;
  },
};

export default rule;

import { finding } from '../../engine/checks/helpers/findings.mjs';

// Converted from engineering-practices: a GENERATED file gets a `merge=ours`
// .gitattributes entry so a conflicting merge resolves automatically instead of
// being hand-edited (which desyncs it from its source). Directional → advisory.
function globToRe(glob) {
  return new RegExp(
    `^${glob.replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*').replace(/\?/g, '.')}$`
  );
}

const rule = {
  id: 'generated-merge-driver',
  severity: 'advisory',
  description: 'A GENERATED file needs a .gitattributes merge=ours entry',
  doc: 'packs/basics/RULES.md',
  why: 'without merge=ours a conflicting merge on a generated file gets hand-resolved and desyncs from its source',

  run(ctx) {
    // allFiles, not files: this is the one check that reasons *about* generated files,
    // so it must see them even when a repo also marks them linguist-generated (which
    // the engine otherwise drops from ctx.files).
    const generated = ctx.allFiles.filter((f) => f.split('/').pop().includes('GENERATED'));
    if (!generated.length) return [];
    const patterns = (ctx.read('.gitattributes') || '')
      .split('\n')
      .filter((l) => /\bmerge=ours\b/.test(l) && !l.trim().startsWith('#'))
      .map((l) => globToRe(l.trim().split(/\s+/)[0]));

    return generated
      .filter((f) => !patterns.some((re) => re.test(f) || re.test(f.split('/').pop())))
      .map((f) => finding(rule, {
        file: f,
        what: 'a GENERATED file with no merge=ours .gitattributes entry',
        fix: `add \`${f.split('/').pop()} merge=ours\` to .gitattributes (plus a one-time \`git config merge.ours.driver true\`) so a conflicting merge auto-resolves`,
      }));
  },
};

export default rule;

